// src/lib/scenarios.ts
function applyScenarios(p, ids, asOf = "2026-11-17") {
  const next = { ...p };
  if (ids.includes("english")) {
    next.english = "superior";
    next.englishDate = asOf;
  }
  if (ids.includes("language")) {
    next.communityLanguage = true;
    next.communityLanguageExpiry = "";
  }
  if (ids.includes("australian-work"))
    next.australianYears = [1, 3, 5, 8].find((v) => v > p.australianYears) ?? p.australianYears;
  if (ids.includes("overseas-work"))
    next.overseasYears = [3, 5, 8].find((v) => v > p.overseasYears) ?? p.overseasYears;
  return next;
}

